function s(v) { return String(v == null ? '' : v).trim(); }
function nz(x) { return s(x).toLowerCase().replace(/[^a-z0-9]/g, ''); }

const invRaw = $('Read INVESTORS').all().map(function (i) { return i.json; });
const stRaw = $('Read STARTUPS').all().map(function (i) { return i.json; });
const pipe = $input.all().map(function (i) { return i.json; });
if (pipe.length < 500) { throw new Error('ABORT: PIPELINE only ' + pipe.length); }

const SIX = ['nexcore', 'recex', 'washtro', 'formverse', 'pixelence', 'doffair'];

function toCr(txt) {
  const t = s(txt).replace(/,/g, '');
  if (!t) { return null; }
  let m = t.match(/(?:US\$|\$)\s*([\d.]+)\s*M/i);
  if (m) { return parseFloat(m[1]) * 8.5; }
  m = t.match(/(?:US\$|\$)\s*([\d.]+)\s*K/i);
  if (m) { return parseFloat(m[1]) * 0.0085; }
  m = t.match(/([\d.]+)\s*(?:-|to|–)\s*[\d.]+\s*Cr/i);
  if (m) { return parseFloat(m[1]); }
  m = t.match(/([\d.]+)\s*Cr/i);
  if (m) { return parseFloat(m[1]); }
  m = t.match(/([\d.]+)\s*Lakh/i);
  if (m) { return parseFloat(m[1]) / 100; }
  return null;
}

const byInv = {};
for (const r of invRaw) {
  const k = nz(r.investor);
  if (!k || byInv[k]) { continue; }
  byInv[k] = { name: s(r.investor), cheque: s(r.cheque_inr_cr), floor: toCr(r.cheque_inr_cr),
    stage: s(r.stage), sector: s(r.sector) };
}

const out = [];
for (const r of stRaw) {
  const name = s(r.startup);
  if (SIX.indexOf(nz(name)) < 0) { continue; }
  const raise = toCr(r.raise_inr_cr);
  const mine = pipe.filter(function (p) { return nz(p.startup) === nz(name); });

  const overCheque = [];
  let unknownFloor = 0, ok = 0, sent = 0;
  const prios = {};
  for (const p of mine) {
    if (s(p.deal_shared).toLowerCase() === 'yes') { sent++; }
    const pr = s(p.priority);
    prios[pr] = (prios[pr] || 0) + 1;
    const iv = byInv[nz(p.investor)];
    if (!iv) { continue; }
    if (iv.floor === null) { unknownFloor++; continue; }
    if (raise !== null && iv.floor > raise) {
      overCheque.push({ investor: iv.name, min_cheque: iv.cheque, floor_cr: Math.round(iv.floor * 100) / 100,
        shared: s(p.deal_shared), response: s(p.investor_response), priority: pr });
    } else { ok++; }
  }
  out.push({ startup: name, raise_raw: s(r.raise_inr_cr), raise_cr: raise,
    pipeline_rows: mine.length, already_sent: sent,
    cheque_ok: ok, cheque_unknown: unknownFloor, cheque_violations: overCheque.length,
    priority_spread: prios, violations: overCheque.slice(0, 12) });
}
out.sort(function (a, b) { return b.cheque_violations - a.cheque_violations; });
return [{ json: { checked: out.length, rows: out } }];
